// Advanced: model expected kWh from hourly radiation/cloud-cover data, then compare
// to actual reported production to get an efficiency ratio and detect hard faults.
const cfg = $('Set - Config').first().json;
const weather = $input.first().json;
const solar = $('HTTP Request - Fetch Solar Production Data').first().json;

const hourlyTimes = (weather.hourly && weather.hourly.time) || [];
const cloudCover = (weather.hourly && weather.hourly.cloudcover) || [];
const radiation = (weather.hourly && weather.hourly.shortwave_radiation) || [];

const PERFORMANCE_DERATE = 0.8; // inverter, wiring and soiling losses
const STC_RADIATION_WM2 = 1000; // standard test condition irradiance used to normalize capacity factor
const DAYLIGHT_RADIATION_THRESHOLD = 50; // W/m^2 above which we count the hour as daylight

let expectedKwh = 0;
let daylightHours = 0;

for (let i = 0; i < hourlyTimes.length; i++) {
  const rad = radiation[i] || 0;
  if (rad > DAYLIGHT_RADIATION_THRESHOLD) {
    daylightHours += 1;
    const cloudFactor = 1 - ((cloudCover[i] || 0) / 100) * 0.75; // clouds cut output, not to zero
    const capacityFactor = Math.min(1, rad / STC_RADIATION_WM2);
    expectedKwh += cfg.systemCapacityKw * capacityFactor * cloudFactor * PERFORMANCE_DERATE;
  }
}
expectedKwh = Math.round(expectedKwh * 100) / 100;

const actualKwh = solar.totalProducedKwh || solar.producedKwh || 0;
const efficiencyRatio = expectedKwh > 0 ? actualKwh / expectedKwh : null;
const efficiencyPercent = efficiencyRatio !== null ? Math.round(efficiencyRatio * 100) : null;
const zeroProductionDuringDaylight = daylightHours > 0 && actualKwh <= 0.05;

return [{
  json: {
    ...cfg,
    expectedKwh,
    actualProducedKwh: actualKwh,
    daylightHours,
    efficiencyPercent,
    zeroProductionDuringDaylight
  }
}];

// Advanced: match production and usage by interval, compute self-consumption,
// grid import/export, peak usage time, and a peak/off-peak-weighted import cost.
const ctx = $('JS - Compute Expected Solar Output & Efficiency Ratio').first().json;
const usage = $('HTTP Request - Fetch Grid Usage Data').first().json;
const production = $('HTTP Request - Fetch Solar Production Data').first().json;

const productionIntervals = production.intervals || [];
const usageIntervals = usage.intervals || [];

const usageByTime = {};
usageIntervals.forEach(u => { usageByTime[u.timestamp] = u.consumedKwh || 0; });

let totalSelfConsumed = 0;
let totalGridImport = 0;
let totalGridExport = 0;
let peakUsageInterval = null;
let peakUsageValue = -Infinity;

function isPeakHour(timestamp) {
  const hour = new Date(timestamp).getHours();
  return hour >= ctx.peakHoursStart && hour < ctx.peakHoursEnd;
}

let gridImportCost = 0;

productionIntervals.forEach(p => {
  const produced = p.producedKwh || 0;
  const consumed = usageByTime[p.timestamp] || 0;
  const selfConsumed = Math.min(produced, consumed);
  totalSelfConsumed += selfConsumed;

  const importAmount = Math.max(0, consumed - produced);
  const exportAmount = Math.max(0, produced - consumed);
  totalGridImport += importAmount;
  totalGridExport += exportAmount;

  const rate = isPeakHour(p.timestamp) ? ctx.tariffPeakRate : ctx.tariffOffPeakRate;
  gridImportCost += importAmount * rate;

  if (consumed > peakUsageValue) { peakUsageValue = consumed; peakUsageInterval = p.timestamp; }
});

const totalConsumedKwh = Object.values(usageByTime).reduce((sum, v) => sum + v, 0);
const selfConsumptionRatio = totalConsumedKwh > 0 ? totalSelfConsumed / totalConsumedKwh : 0;

return [{
  json: {
    ...ctx,
    totalConsumedKwh: Math.round(totalConsumedKwh * 100) / 100,
    totalSelfConsumedKwh: Math.round(totalSelfConsumed * 100) / 100,
    totalGridImportKwh: Math.round(totalGridImport * 100) / 100,
    totalGridExportKwh: Math.round(totalGridExport * 100) / 100,
    selfConsumptionRatio: Math.round(selfConsumptionRatio * 1000) / 1000,
    peakUsageInterval,
    peakUsageValue: peakUsageValue === -Infinity ? 0 : Math.round(peakUsageValue * 100) / 100,
    gridImportCost: Math.round(gridImportCost * 100) / 100
  }
}];

// Advanced: combine both analyses into a severity level, troubleshooting checklist
// and a human-readable report/alert message.
const ctx = $('JS - Analyze Usage vs Production & Compute Net Energy Balance').first().json;

let severity = 'none';
const checklist = [];

if (ctx.zeroProductionDuringDaylight) {
  severity = 'critical';
  checklist.push('Check inverter power/connectivity status.');
  checklist.push('Check for tripped breakers on the solar circuit.');
  checklist.push('Inspect panels for physical damage or full shading.');
} else if (ctx.efficiencyPercent !== null && ctx.efficiencyPercent < (100 - ctx.criticalThresholdPercent)) {
  severity = 'critical';
  checklist.push('Compare per-panel output if microinverters/optimizers are available.');
  checklist.push('Check for new shading (trees, construction) or soiling on panels.');
  checklist.push('Confirm the weather-model assumptions match on-site conditions.');
} else if (ctx.efficiencyPercent !== null && ctx.efficiencyPercent < (100 - ctx.underperformanceThresholdPercent)) {
  severity = 'warning';
  checklist.push('Monitor over the next few days for a persistent trend.');
  checklist.push('Consider a panel cleaning if it has been a while.');
}

const alertRequired = severity !== 'none';

const message = alertRequired
  ? 'Solar performance ' + severity.toUpperCase() + ': producing ' + ctx.actualProducedKwh + ' kWh vs an expected ' + ctx.expectedKwh + ' kWh (' + ctx.efficiencyPercent + '% efficiency). Self-consumption: ' + Math.round(ctx.selfConsumptionRatio * 100) + '%. Grid import cost today: $' + ctx.gridImportCost + '.'
  : 'Solar system performing as expected: ' + ctx.actualProducedKwh + ' kWh produced (' + ctx.efficiencyPercent + '% of forecast). Self-consumption: ' + Math.round(ctx.selfConsumptionRatio * 100) + '%, grid import cost: $' + ctx.gridImportCost + '.';

return [{
  json: {
    ...ctx,
    severity,
    alertRequired,
    checklist,
    reportMessage: message
  }
}];

